insert into public.recipes
  (slug, title, description, preparation_minutes, prep_minutes,
   cook_minutes, difficulty, servings, tags, equipment, instructions,
   step_titles, step_minutes, source, source_license,
   source_attribution, access_level)
values
  ('livo-protein-oats', 'Protein-Beeren-Oats', 'Cremiges Frühstück aus Haferflocken, Skyr und Beeren – ganz ohne Kochen.', 8, 8, 0, 'Einfach', 1, array['Frühstück', 'High Protein', 'Schnell', 'Vegetarisch']::text[], array['Schüssel', 'Löffel']::text[], array['Die Haferflocken mit 4 EL Wasser in einer Schüssel verrühren und 3 Minuten quellen lassen.', 'Den Skyr dazugeben und alles glatt rühren, bis eine cremige Masse entsteht.', 'Die Beeren darauf verteilen und die Oats sofort servieren.']::text[], array['Hafer einweichen', 'Skyr unterrühren', 'Toppen']::text[], array[3, 0, 0]::integer[], 'livo_original', 'LIVO original', 'LIVO recipe team', 'free'),
  ('livo-vegetable-egg-pan', 'Gemüse-Ei-Pfanne', 'Warme Pfanne mit Tomate, Paprika und Zwiebel, in der zwei Eier sanft stocken.', 15, 5, 10, 'Einfach', 1, array['Abendessen', 'Frühstück', 'Vegetarisch', 'Schnell']::text[], array['Beschichtete Pfanne mit Deckel', 'Schneidebrett und Messer']::text[], array['Zwiebel fein würfeln, Paprika in Streifen und Tomaten in Würfel schneiden.', 'Das Öl in der Pfanne bei mittlerer Hitze erwärmen. Zwiebel und Paprika darin 4 Minuten braten, bis sie weich werden.', 'Die Tomaten dazugeben, salzen und 2 Minuten sanft köcheln lassen, bis eine stückige Sauce entsteht.', 'Zwei Mulden in das Gemüse drücken, die Eier hineinschlagen und mit Deckel bei niedriger Hitze etwa 4 Minuten stocken lassen, bis das Eiweiß fest ist.', 'Mit Pfeffer bestreuen und direkt aus der Pfanne servieren.']::text[], array['Gemüse schneiden', 'Anbraten', 'Tomaten einkochen', 'Eier stocken lassen', 'Servieren']::text[], array[0, 4, 2, 4, 0]::integer[], 'livo_original', 'LIVO original', 'LIVO recipe team', 'free'),
  ('livo-salmon-avocado-rice', 'Lachs-Avocado-Reis', 'Gebratener Lachs auf Reis mit Avocado und einem Spritzer Zitrone.', 25, 8, 17, 'Mittel', 2, array['Abendessen', 'High Protein', 'Pescetarisch']::text[], array['Kleiner Topf mit Deckel', 'Beschichtete Pfanne', 'Schneidebrett und Messer']::text[], array['Den gekochten Reis mit 2 EL Wasser in einem kleinen Topf mit Deckel bei niedriger Hitze etwa 5 Minuten erwärmen.', 'Den Lachs trocken tupfen und von beiden Seiten mit Salz und Pfeffer würzen.', 'Die Pfanne ohne Öl bei mittlerer Hitze erwärmen. Den Lachs mit der Hautseite nach unten 5 Minuten braten, wenden und weitere 3 Minuten garen, bis er innen nicht mehr glasig ist.', 'Die Avocado halbieren, entkernen, in Scheiben schneiden und mit etwas Zitronensaft beträufeln.', 'Reis auf zwei Teller verteilen, Lachs und Avocado darauf legen und mit restlichem Zitronensaft servieren.']::text[], array['Reis erwärmen', 'Lachs vorbereiten', 'Lachs braten', 'Avocado schneiden', 'Anrichten']::text[], array[5, 0, 8, 0, 0]::integer[], 'livo_original', 'LIVO original', 'LIVO recipe team', 'premium'),
  ('livo-avocado-egg-bowl', 'Avocado-Ei-Bowl', 'Einfache Bowl mit wachsweichen Eiern, Avocado und Tomate.', 12, 4, 8, 'Einfach', 1, array['Frühstück', 'Mittagessen', 'Vegetarisch', 'Schnell']::text[], array['Kleiner Topf', 'Schneidebrett und Messer', 'Schüssel']::text[], array['Die Eier in kochendes Wasser legen und 7 Minuten wachsweich kochen. Danach kalt abschrecken.', 'Avocado und Tomate würfeln und die Avocado sofort mit Zitronensaft beträufeln.', 'Die Eier pellen, halbieren und mit Avocado und Tomate in eine Schüssel geben. Mit Salz und Pfeffer würzen.']::text[], array['Eier kochen', 'Schneiden', 'Anrichten']::text[], array[7, 0, 0]::integer[], 'livo_original', 'LIVO original', 'LIVO recipe team', 'free'),
  ('livo-tomato-rice-pan', 'Tomaten-Reis-Pfanne', 'Schnelle Resteverwertung: gekochter Reis mit Tomaten, Zwiebel und Paprikapulver.', 20, 7, 13, 'Einfach', 2, array['Mittagessen', 'Vegan', 'Budget', 'Schnell']::text[], array['Große Pfanne', 'Schneidebrett und Messer']::text[], array['Zwiebel und Knoblauch fein hacken, die Tomaten in kleine Würfel schneiden.', 'Das Öl in der Pfanne erhitzen und die Zwiebel darin 3 Minuten glasig dünsten. Knoblauch und Tomatenmark 1 Minute mitrösten.', 'Tomaten und Paprikapulver dazugeben und 4 Minuten köcheln lassen, bis die Tomaten zerfallen.', 'Den Reis unterheben und unter Wenden 5 Minuten braten, bis er heiß ist. Mit Salz und Pfeffer abschmecken.']::text[], array['Vorbereiten', 'Anschwitzen', 'Tomaten garen', 'Reis unterheben']::text[], array[0, 4, 4, 5]::integer[], 'livo_original', 'LIVO original', 'LIVO recipe team', 'free'),
  ('livo-skyr-berry-bowl', 'Skyr-Beeren-Bowl', 'Schneller Snack aus Skyr, Beeren und einem Hauch Honig.', 5, 5, 0, 'Einfach', 1, array['Snack', 'High Protein', 'Schnell', 'Vegetarisch']::text[], array['Schüssel', 'Löffel']::text[], array['Den Skyr in eine Schüssel geben und kurz glatt rühren, damit er cremiger wird.', 'Die Beeren darauf verteilen, gefrorene Beeren vorher auftauen lassen.', 'Den Honig darüberträufeln und die Bowl direkt servieren.']::text[], array['Skyr cremig rühren', 'Beeren verteilen', 'Beträufeln']::text[], array[0, 0, 0]::integer[], 'livo_original', 'LIVO original', 'LIVO recipe team', 'free'),
  ('livo-salmon-tomato-bowl', 'Lachs-Tomaten-Bowl', 'Lachs mit Reis, frischen Tomaten und kurz gebratener Zucchini.', 25, 8, 17, 'Mittel', 2, array['Abendessen', 'Mittagessen', 'High Protein', 'Pescetarisch']::text[], array['Kleiner Topf mit Deckel', 'Beschichtete Pfanne', 'Schneidebrett und Messer']::text[], array['Den gekochten Reis mit 2 EL Wasser in einem Topf mit Deckel bei niedriger Hitze 5 Minuten erwärmen.', 'Das Öl in der Pfanne erhitzen und die Zucchini darin 4 Minuten braten, leicht salzen und herausnehmen.', 'Den Lachs salzen und in derselben Pfanne bei mittlerer Hitze 5 Minuten auf der Hautseite und 3 Minuten auf der anderen Seite garen.', 'Reis, Zucchini, Tomatenwürfel und Lachs in zwei Schüsseln verteilen, mit Zitronensaft und Pfeffer abschmecken.']::text[], array['Reis erwärmen', 'Zucchini braten', 'Lachs braten', 'Anrichten']::text[], array[5, 4, 8, 0]::integer[], 'livo_original', 'LIVO original', 'LIVO recipe team', 'premium'),
  ('livo-egg-avocado-breakfast', 'Ei-Avocado-Frühstück', 'Spiegeleier mit Avocado, Tomate und einer Scheibe Vollkornbrot.', 10, 4, 6, 'Einfach', 1, array['Frühstück', 'Vegetarisch', 'Schnell']::text[], array['Beschichtete Pfanne', 'Schneidebrett und Messer']::text[], array['Das Öl in der Pfanne bei mittlerer Hitze erwärmen, die Eier hineinschlagen und 4 bis 5 Minuten braten, bis das Eiweiß fest ist.', 'Avocado in Scheiben und Tomate in Spalten schneiden, das Brot nach Wunsch toasten.', 'Eier, Avocado, Tomate und Brot auf einem Teller anrichten und mit Salz und Pfeffer würzen.']::text[], array['Spiegeleier braten', 'Schneiden', 'Anrichten']::text[], array[5, 0, 0]::integer[], 'livo_original', 'LIVO original', 'LIVO recipe team', 'premium'),
  ('livo-skyr-oat-cup', 'Skyr-Hafer-Cup', 'Geschichteter Becher mit gerösteten Haferflocken, Skyr und Beeren.', 8, 5, 3, 'Einfach', 1, array['Frühstück', 'High Protein', 'Vegetarisch', 'Schnell']::text[], array['Kleine Pfanne', 'Glas oder Becher']::text[], array['Die Haferflocken in einer Pfanne ohne Fett unter Rühren 3 Minuten goldbraun rösten und abkühlen lassen.', 'Abwechselnd Skyr, geröstete Haferflocken und Beeren in ein Glas schichten.', 'Mit Beeren abschließen, den Honig darüberträufeln und sofort servieren.']::text[], array['Hafer rösten', 'Schichten', 'Vollenden']::text[], array[3, 0, 0]::integer[], 'livo_original', 'LIVO original', 'LIVO recipe team', 'premium'),
  ('livo-rice-egg-bowl', 'Reis-Ei-Bowl', 'Gebratener Gemüsereis mit Erbsen und Möhren, dazu ein Spiegelei – ideal für Reis vom Vortag.', 15, 5, 10, 'Einfach', 1, array['Mittagessen', 'Abendessen', 'Vegetarisch', 'Budget', 'Schnell']::text[], array['Große beschichtete Pfanne', 'Reibe', 'Schneidebrett und Messer']::text[], array['Das Öl in der Pfanne erhitzen. Möhre, Erbsen und den weißen Teil der Frühlingszwiebel darin 3 Minuten braten.', 'Den Reis dazugeben und unter gelegentlichem Wenden 4 Minuten braten, bis er heiß und leicht knusprig ist. Salzen und pfeffern.', 'Den Reis an den Rand schieben, die Eier in die freie Stelle schlagen und 3 Minuten braten, bis das Eiweiß fest ist.', 'Reis in eine Schüssel geben, Spiegeleier und Tomate darauf legen und mit dem Grün der Frühlingszwiebel bestreuen.']::text[], array['Gemüse anbraten', 'Reis braten', 'Spiegelei', 'Anrichten']::text[], array[3, 4, 3, 0]::integer[], 'livo_original', 'LIVO original', 'LIVO recipe team', 'free'),
  ('livo-apfel-zimt-porridge', 'Apfel-Zimt-Porridge', 'Warmer Haferbrei mit Milch, gebratenen Apfelwürfeln und Zimt – aus fünf Vorratszutaten.', 12, 3, 9, 'Einfach', 1, array['Frühstück', 'Vegetarisch', 'Budget', 'Schnell']::text[], array['Kleiner Topf', 'Kleine Pfanne', 'Schneidebrett und Messer']::text[], array['Haferflocken, Milch und Salz in einem Topf aufkochen und bei niedriger Hitze unter Rühren 5 Minuten köcheln lassen.', 'Den Apfel würfeln und in einer kleinen Pfanne mit 2 EL Wasser, Honig und Zimt 4 Minuten weich dünsten.', 'Das Porridge in eine Schale füllen und die warmen Zimtäpfel darauf verteilen.']::text[], array['Porridge kochen', 'Apfel braten', 'Anrichten']::text[], array[5, 4, 0]::integer[], 'livo_original', 'LIVO original', 'LIVO recipe team', 'free'),
  ('livo-ruehrei-vollkornbrot', 'Rührei auf Vollkornbrot', 'Cremiges Rührei mit Schnittlauch auf Vollkornbrot – schnell, sättigend und mit wenigen Zutaten.', 10, 4, 6, 'Einfach', 1, array['Frühstück', 'High Protein', 'Vegetarisch', 'Schnell']::text[], array['Beschichtete Pfanne', 'Schüssel', 'Schneebesen oder Gabel']::text[], array['Eier, Milch und Salz in einer Schüssel mit einer Gabel verquirlen, bis keine Eiweißschlieren mehr zu sehen sind.', 'Die Butter in der Pfanne bei niedriger bis mittlerer Hitze schmelzen. Die Eier hineingießen und mit einem Pfannenwender langsam vom Rand zur Mitte schieben, bis sie gerade gestockt, aber noch feucht sind.', 'Das Brot währenddessen toasten oder frisch lassen und auf einen Teller legen.', 'Das Rührei auf dem Brot verteilen, mit Schnittlauch und Pfeffer bestreuen und sofort essen.']::text[], array['Eier verquirlen', 'Langsam stocken', 'Brot vorbereiten', 'Anrichten']::text[], array[0, 4, 2, 0]::integer[], 'livo_original', 'LIVO original', 'LIVO recipe team', 'free'),
  ('livo-bananen-hafer-pfannkuchen', 'Bananen-Hafer-Pfannkuchen', 'Kleine, saftige Pfannkuchen aus Haferflocken, Banane und Ei – ohne Mehl.', 20, 6, 14, 'Einfach', 2, array['Frühstück', 'Vegetarisch', 'Schnell']::text[], array['Pürierstab oder Mixer', 'Beschichtete Pfanne', 'Schüssel']::text[], array['Haferflocken, eine Banane, Eier, Milch, Zimt und Salz mit dem Pürierstab zu einem glatten Teig mixen.', 'Den Teig 5 Minuten ruhen lassen, damit die Haferflocken Flüssigkeit aufnehmen und der Teig dicker wird.', 'Die Pfanne mit wenig Öl bei mittlerer Hitze erwärmen. Pro Pfannkuchen 2 EL Teig hineingeben und je Seite etwa 2 Minuten goldbraun backen.', 'Die Pfannkuchen stapeln und mit der restlichen, in Scheiben geschnittenen Banane belegen.']::text[], array['Teig mixen', 'Quellen lassen', 'Ausbacken', 'Belegen']::text[], array[2, 5, 8, 0]::integer[], 'livo_original', 'LIVO original', 'LIVO recipe team', 'premium'),
  ('livo-overnight-oats-banane', 'Overnight Oats mit Joghurt und Banane', 'Am Vorabend in zwei Minuten angerührt, morgens fertig: Haferflocken mit Joghurt, Milch und Banane.', 485, 5, 0, 'Einfach', 1, array['Frühstück', 'Vegetarisch', 'Meal Prep', 'Budget']::text[], array['Schraubglas oder Schüssel mit Deckel', 'Löffel']::text[], array['Haferflocken, Joghurt, Milch und Zimt in einem Glas gründlich verrühren.', 'Das Glas verschließen und mindestens 8 Stunden im Kühlschrank quellen lassen.', 'Morgens kurz umrühren, die Banane in Scheiben schneiden und darauf verteilen.']::text[], array['Anrühren', 'Über Nacht quellen', 'Toppen']::text[], array[0, 480, 0]::integer[], 'livo_original', 'LIVO original', 'LIVO recipe team', 'premium'),
  ('livo-pfannkuchen', 'Pfannkuchen (Grundrezept)', 'Dünne Pfannkuchen aus Mehl, Milch und Eiern – süß oder herzhaft zu füllen.', 35, 15, 20, 'Einfach', 3, array['Frühstück', 'Snack', 'Vegetarisch', 'Budget']::text[], array['Schüssel', 'Schneebesen', 'Beschichtete Pfanne', 'Suppenkelle']::text[], array['Mehl und Salz in eine Schüssel geben. Nach und nach die Milch unterrühren, bis ein glatter Teig ohne Klümpchen entsteht. Dann die Eier einrühren.', 'Den Teig 10 Minuten ruhen lassen, dann wird er geschmeidiger und die Pfannkuchen reißen weniger.', 'Die Pfanne mit wenig Öl bei mittlerer Hitze erwärmen. Eine Kelle Teig hineingeben, durch Schwenken dünn verteilen und etwa 1 Minute backen, bis der Rand sich löst.', 'Den Pfannkuchen wenden und noch 30 Sekunden backen. So weiterverfahren, bis der Teig aufgebraucht ist – ergibt etwa 8 Stück.']::text[], array['Teig rühren', 'Ruhen lassen', 'Ausbacken', 'Wenden']::text[], array[0, 10, 1, 18]::integer[], 'livo_original', 'LIVO original', 'LIVO recipe team', 'premium'),
  ('livo-arme-ritter', 'Arme Ritter mit Zimt', 'Brot vom Vortag in Eiermilch getaucht und goldbraun gebraten – mit Zimt und Honig.', 20, 8, 12, 'Einfach', 2, array['Frühstück', 'Snack', 'Vegetarisch', 'Budget']::text[], array['Flacher Teller', 'Schneebesen oder Gabel', 'Große Pfanne']::text[], array['Eier, Milch, die Hälfte des Zimts und Salz in einem tiefen Teller verquirlen.', 'Die Brotscheiben nacheinander von beiden Seiten je 20 Sekunden in die Eiermilch legen, bis sie sich vollgesogen haben.', 'Die Butter in der Pfanne bei mittlerer Hitze schmelzen und die Scheiben je Seite 3 bis 4 Minuten goldbraun braten.', 'Mit dem restlichen Zimt bestäuben und mit Honig beträufelt warm servieren.']::text[], array['Eiermilch', 'Einweichen', 'Braten', 'Servieren']::text[], array[0, 2, 8, 0]::integer[], 'livo_original', 'LIVO original', 'LIVO recipe team', 'premium'),
  ('livo-bananen-quark', 'Bananen-Quark mit Haferflocken', 'Cremiger Quark mit zerdrückter Banane, Haferflocken und Zimt – ein sättigender Snack ohne Kochen.', 5, 5, 0, 'Einfach', 1, array['Snack', 'Frühstück', 'High Protein', 'Vegetarisch', 'Schnell']::text[], array['Schüssel', 'Gabel']::text[], array['Den Quark mit der Milch in einer Schüssel glatt rühren, bis er cremig ist.', 'Die Hälfte der Banane mit einer Gabel zerdrücken und mit dem Zimt unter den Quark rühren.', 'Die restliche Banane in Scheiben schneiden, mit den Haferflocken auf den Quark geben und mit Honig beträufeln.']::text[], array['Quark cremig rühren', 'Banane zerdrücken', 'Toppen']::text[], array[0, 0, 0]::integer[], 'livo_original', 'LIVO original', 'LIVO recipe team', 'premium'),
  ('livo-pellkartoffeln-kraeuterquark', 'Pellkartoffeln mit Kräuterquark', 'Der Klassiker aus dem Vorrat: in der Schale gekochte Kartoffeln mit frischem Kräuterquark.', 35, 10, 25, 'Einfach', 2, array['Mittagessen', 'Abendessen', 'Vegetarisch', 'Budget', 'High Protein']::text[], array['Großer Topf mit Deckel', 'Schüssel', 'Schneidebrett und Messer']::text[], array['Die Kartoffeln gründlich waschen, mit Wasser bedecken, etwas Salz zugeben und zugedeckt 20 bis 25 Minuten kochen, bis sich ein Messer leicht hineinstechen lässt.', 'Währenddessen Quark und Milch glatt rühren. Schnittlauch, Knoblauch, Salz und Pfeffer untermischen.', 'Die Kartoffeln abgießen und kurz ausdampfen lassen. Nach Wunsch pellen oder mit Schale essen.', 'Die Kartoffeln mit dem Kräuterquark auf Tellern anrichten.']::text[], array['Kartoffeln kochen', 'Quark anrühren', 'Abgießen', 'Servieren']::text[], array[25, 0, 0, 0]::integer[], 'livo_original', 'LIVO original', 'LIVO recipe team', 'free'),
  ('livo-bratkartoffeln-spiegelei', 'Bratkartoffeln mit Spiegelei', 'Knusprige Bratkartoffeln mit Zwiebeln und zwei Spiegeleiern – aus gekochten Kartoffeln vom Vortag.', 30, 8, 22, 'Einfach', 2, array['Abendessen', 'Mittagessen', 'Vegetarisch', 'Budget']::text[], array['Große Pfanne, am besten Gusseisen', 'Zweite Pfanne für die Eier', 'Schneidebrett und Messer']::text[], array['Die gekochten Kartoffeln in Scheiben oder Würfel schneiden, die Zwiebel in Streifen.', 'Das Öl in der großen Pfanne stark erhitzen. Die Kartoffeln in einer Schicht hineingeben und 8 Minuten braten, ohne sie zu bewegen.', 'Die Kartoffeln wenden, die Zwiebeln dazugeben und weitere 8 Minuten bei mittlerer Hitze braten, bis alles goldbraun ist. Mit Salz, Pfeffer und Paprikapulver würzen.', 'Währenddessen die Butter in der zweiten Pfanne schmelzen, die Eier hineinschlagen und 4 Minuten braten, bis das Eiweiß fest ist.', 'Die Bratkartoffeln auf zwei Teller verteilen und je zwei Spiegeleier darauf legen.']::text[], array['Schneiden', 'Kartoffeln braten', 'Wenden und Zwiebeln', 'Spiegeleier', 'Anrichten']::text[], array[0, 8, 8, 4, 0]::integer[], 'livo_original', 'LIVO original', 'LIVO recipe team', 'free'),
  ('livo-kartoffel-moehren-eintopf', 'Kartoffel-Möhren-Eintopf', 'Klarer, wärmender Eintopf mit Kartoffeln, Möhren und Zwiebeln – günstig und gut vorzukochen.', 40, 15, 25, 'Einfach', 3, array['Mittagessen', 'Abendessen', 'Vegan', 'Budget', 'Meal Prep']::text[], array['Großer Topf mit Deckel', 'Sparschäler', 'Schneidebrett und Messer']::text[], array['Kartoffeln schälen und in 2 cm große Würfel schneiden, Möhren in Scheiben und die Zwiebel in Würfel schneiden.', 'Das Öl im Topf erhitzen und die Zwiebel darin 3 Minuten glasig dünsten. Die Möhren 2 Minuten mitdünsten.', 'Kartoffeln und Brühe zugeben, aufkochen und zugedeckt 18 bis 20 Minuten köcheln lassen, bis die Kartoffeln weich sind.', 'Mit Salz und Pfeffer abschmecken und die Petersilie unterrühren.']::text[], array['Gemüse schneiden', 'Anschwitzen', 'Köcheln', 'Abschmecken']::text[], array[0, 5, 20, 0]::integer[], 'livo_original', 'LIVO original', 'LIVO recipe team', 'premium'),
  ('livo-ofenkartoffeln-moehren', 'Ofenkartoffeln mit Möhren und Knoblauch-Joghurt', 'Kartoffeln und Möhren vom Blech mit Paprika-Würze, dazu ein kühler Joghurt-Dip.', 45, 12, 33, 'Einfach', 3, array['Abendessen', 'Mittagessen', 'Vegetarisch', 'Budget']::text[], array['Backblech mit Backpapier', 'Große Schüssel', 'Schneidebrett und Messer']::text[], array['Den Backofen auf 220 °C Ober- und Unterhitze vorheizen und ein Blech mit Backpapier belegen.', 'Kartoffeln, Möhren und Zwiebel in einer Schüssel mit Öl, Paprikapulver, Salz und Pfeffer gründlich vermengen.', 'Das Gemüse in einer Schicht auf dem Blech verteilen und 30 bis 35 Minuten backen, nach der Hälfte der Zeit einmal wenden.', 'Währenddessen den Joghurt mit dem Knoblauch und einer Prise Salz verrühren.', 'Die Ofenkartoffeln mit dem Knoblauch-Joghurt servieren.']::text[], array['Ofen vorheizen', 'Würzen', 'Backen', 'Dip rühren', 'Servieren']::text[], array[0, 0, 33, 0, 0]::integer[], 'livo_original', 'LIVO original', 'LIVO recipe team', 'premium'),
  ('livo-kartoffelpuffer-apfelmus', 'Kartoffelpuffer mit Apfelmus', 'Knusprige Reibekuchen aus rohen Kartoffeln und Zwiebel, klassisch mit Apfelmus.', 45, 20, 25, 'Mittel', 3, array['Mittagessen', 'Snack', 'Vegetarisch', 'Budget']::text[], array['Reibe', 'Sauberes Küchentuch', 'Große Schüssel', 'Große Pfanne', 'Küchenpapier']::text[], array['Kartoffeln und Zwiebel fein reiben.', 'Die Masse in ein sauberes Küchentuch geben und kräftig ausdrücken, bis kaum noch Flüssigkeit austritt.', 'Kartoffelmasse, Ei, Mehl und Salz in einer Schüssel gut vermengen.', 'Etwas Öl in der Pfanne stark erhitzen. Je 2 EL Masse hineingeben, flach drücken und von jeder Seite 3 bis 4 Minuten goldbraun backen. Nach Bedarf Öl nachgießen.', 'Die Puffer kurz auf Küchenpapier abtropfen lassen und heiß mit Apfelmus servieren.']::text[], array['Reiben', 'Ausdrücken', 'Teig mischen', 'Ausbacken', 'Abtropfen und servieren']::text[], array[0, 0, 0, 25, 0]::integer[], 'livo_original', 'LIVO original', 'LIVO recipe team', 'premium'),
  ('livo-kartoffel-tortilla', 'Kartoffel-Tortilla', 'Spanisches Kartoffelomelett aus nur fünf Zutaten: Kartoffeln, Zwiebeln, Eier, Olivenöl und Salz.', 45, 15, 30, 'Mittel', 3, array['Mittagessen', 'Abendessen', 'Vegetarisch', 'Budget', 'Meal Prep']::text[], array['Beschichtete Pfanne (ca. 24 cm) mit Deckel', 'Großer Teller zum Wenden', 'Schüssel']::text[], array['Das Öl in der Pfanne erhitzen. Kartoffeln und Zwiebeln hineingeben, salzen und zugedeckt bei mittlerer Hitze 15 Minuten weich garen, dabei gelegentlich wenden.', 'Die Eier in einer großen Schüssel mit einer Prise Salz verquirlen. Die weichen Kartoffeln und Zwiebeln unterheben und 5 Minuten ziehen lassen.', 'Die Masse zurück in die leicht geölte Pfanne geben und bei niedriger Hitze zugedeckt 8 Minuten stocken lassen, bis der Rand fest ist.', 'Einen großen Teller auf die Pfanne legen, die Tortilla vorsichtig darauf stürzen und zurück in die Pfanne gleiten lassen. Weitere 3 Minuten garen.', 'Die Tortilla 5 Minuten ruhen lassen und dann in Stücke schneiden.']::text[], array['Kartoffeln garen', 'Eier verquirlen', 'Stocken lassen', 'Wenden', 'Ruhen lassen']::text[], array[15, 5, 8, 3, 5]::integer[], 'livo_original', 'LIVO original', 'LIVO recipe team', 'premium'),
  ('livo-kartoffelsalat-gurke', 'Kartoffelsalat mit Gurke und Joghurt', 'Leichter Kartoffelsalat mit Gurke, Frühlingszwiebeln und Joghurt-Dressing.', 45, 15, 25, 'Einfach', 3, array['Mittagessen', 'Abendessen', 'Vegetarisch', 'Budget', 'Meal Prep']::text[], array['Großer Topf', 'Große Schüssel', 'Schneidebrett und Messer']::text[], array['Die Kartoffeln in der Schale 20 bis 25 Minuten gar kochen, abgießen und etwas abkühlen lassen.', 'Die Gurke in dünne Scheiben schneiden, mit einer Prise Salz mischen und 10 Minuten ziehen lassen. Dann das Wasser abgießen.', 'Joghurt, Öl, Zitronensaft, Salz und Pfeffer zu einem glatten Dressing verrühren.', 'Die Kartoffeln pellen, in Scheiben schneiden und noch lauwarm mit Gurke, Frühlingszwiebeln und Dressing vermengen.', 'Den Salat mindestens 15 Minuten ziehen lassen und mit Schnittlauch bestreut servieren.']::text[], array['Kartoffeln kochen', 'Gurke salzen', 'Dressing', 'Mischen', 'Ziehen lassen']::text[], array[25, 10, 0, 0, 15]::integer[], 'livo_original', 'LIVO original', 'LIVO recipe team', 'premium'),
  ('livo-rote-linsen-dal', 'Rote-Linsen-Dal mit Reis', 'Cremiges Linsencurry aus roten Linsen und Dosentomaten, dazu Reis – vegan, günstig und sättigend.', 35, 10, 25, 'Einfach', 4, array['Mittagessen', 'Abendessen', 'Vegan', 'Budget', 'Meal Prep']::text[], array['Großer Topf mit Deckel', 'Topf für den Reis', 'Sieb']::text[], array['Die Linsen in einem Sieb unter kaltem Wasser spülen, bis das Wasser klar abläuft.', 'Den Reis mit 500 ml Wasser und einer Prise Salz aufkochen und zugedeckt bei niedriger Hitze 15 Minuten garen. Danach 5 Minuten ruhen lassen.', 'Das Öl im großen Topf erhitzen. Zwiebel 3 Minuten glasig dünsten, dann Knoblauch, Curry und Kreuzkümmel 1 Minute mitrösten.', 'Linsen, Dosentomaten und Brühe zugeben, aufkochen und 15 bis 18 Minuten offen köcheln lassen, bis die Linsen zerfallen. Gelegentlich umrühren.', 'Mit Zitronensaft und Salz abschmecken und das Dal mit dem Reis servieren.']::text[], array['Linsen spülen', 'Reis kochen', 'Anschwitzen', 'Dal köcheln', 'Abschmecken']::text[], array[0, 20, 4, 18, 0]::integer[], 'livo_original', 'LIVO original', 'LIVO recipe team', 'free'),
  ('livo-mujaddara', 'Linsen-Reis mit Röstzwiebeln (Mujaddara)', 'Orientalischer Klassiker aus Linsen, Reis und viel karamellisierter Zwiebel, dazu Joghurt.', 55, 10, 45, 'Mittel', 4, array['Abendessen', 'Mittagessen', 'Vegetarisch', 'Budget', 'Meal Prep']::text[], array['Großer Topf mit Deckel', 'Große Pfanne', 'Sieb']::text[], array['Die Linsen spülen, mit 1 l Wasser aufkochen und 15 Minuten köcheln lassen, bis sie fast gar sind. Abgießen.', 'Währenddessen das Öl in der Pfanne erhitzen und die Zwiebeln bei mittlerer Hitze 20 bis 25 Minuten unter gelegentlichem Rühren tief goldbraun rösten. Leicht salzen.', 'Reis, Linsen, Kreuzkümmel, Salz und die Hälfte der Zwiebeln mit 450 ml Wasser in den Topf geben, aufkochen und zugedeckt bei niedriger Hitze 15 Minuten garen.', 'Den Topf vom Herd nehmen und 5 Minuten geschlossen ruhen lassen. Mit einer Gabel auflockern und pfeffern.', 'Den Linsen-Reis anrichten, die übrigen Röstzwiebeln darauf verteilen und mit Joghurt servieren.']::text[], array['Linsen vorkochen', 'Zwiebeln rösten', 'Reis und Linsen garen', 'Ruhen lassen', 'Servieren']::text[], array[15, 25, 15, 5, 0]::integer[], 'livo_original', 'LIVO original', 'LIVO recipe team', 'premium'),
  ('livo-milchreis-zimt', 'Milchreis mit Zimt', 'Cremiger Milchreis aus dem Topf, mit Honig gesüßt und mit Zimt bestäubt.', 40, 5, 35, 'Einfach', 4, array['Snack', 'Frühstück', 'Vegetarisch', 'Budget']::text[], array['Topf mit dickem Boden und Deckel', 'Kochlöffel']::text[], array['Milch und Salz im Topf aufkochen, dabei rühren, damit nichts anbrennt.', 'Den Milchreis einrühren und bei niedrigster Hitze zugedeckt 30 Minuten quellen lassen. Alle 5 Minuten umrühren.', 'Den Honig unterrühren. Der Milchreis ist fertig, wenn die Körner weich und cremig sind.', 'Den Milchreis in Schalen füllen und mit Zimt bestäuben.']::text[], array['Aufkochen', 'Quellen lassen', 'Süßen', 'Servieren']::text[], array[5, 30, 0, 0]::integer[], 'livo_original', 'LIVO original', 'LIVO recipe team', 'premium'),
  ('livo-thunfisch-reis-bowl', 'Thunfisch-Reis-Bowl mit Gurke', 'Reis mit Thunfisch aus der Dose, Gurke, Mais und Joghurt-Zitronen-Dressing.', 25, 10, 15, 'Einfach', 2, array['Mittagessen', 'High Protein', 'Pescetarisch', 'Schnell']::text[], array['Topf mit Deckel', 'Schneidebrett und Messer', 'Kleine Schüssel']::text[], array['Den Reis mit 300 ml Wasser und einer Prise Salz aufkochen und zugedeckt bei niedriger Hitze 15 Minuten garen.', 'Joghurt, Zitronensaft, eine Prise Salz und Pfeffer glatt rühren.', 'Gurke würfeln, Frühlingszwiebel in Ringe schneiden, Mais abtropfen lassen und den Thunfisch mit einer Gabel zerpflücken.', 'Den Reis in zwei Schüsseln verteilen, Thunfisch, Gurke und Mais darauf legen, mit Dressing beträufeln und mit Frühlingszwiebeln bestreuen.']::text[], array['Reis kochen', 'Dressing', 'Schneiden', 'Anrichten']::text[], array[15, 0, 0, 0]::integer[], 'livo_original', 'LIVO original', 'LIVO recipe team', 'premium'),
  ('livo-halal-haehnchen-paprika-reis', 'Halal-Hähnchen-Paprika-Reis', 'Zartes Halal-Hähnchenbrustfilet mit Paprika und Zwiebeln, dazu locker gegarter Reis.', 35, 12, 23, 'Mittel', 3, array['Abendessen', 'Mittagessen', 'High Protein', 'Meal Prep']::text[], array['Topf mit Deckel', 'Große Pfanne', 'Schneidebrett und Messer (separat für rohes Geflügel)']::text[], array['Den Reis mit 400 ml Brühe aufkochen und zugedeckt bei niedriger Hitze 15 Minuten garen, dann 5 Minuten ruhen lassen.', 'Das Halal-Hähnchen in Streifen schneiden und trocken tupfen. Die Hälfte des Öls in der Pfanne stark erhitzen und die Streifen 5 bis 6 Minuten rundum braten, bis sie innen nicht mehr rosa sind. Herausnehmen.', 'Das restliche Öl erhitzen, Zwiebel und Paprika 5 Minuten braten, dann Knoblauch und Paprikapulver 1 Minute mitrösten.', 'Das Halal-Hähnchen zurück in die Pfanne geben, mit 50 ml Brühe ablöschen, salzen, pfeffern und 2 Minuten durchziehen lassen.', 'Den Reis mit der Hähnchen-Paprika-Pfanne anrichten und mit Petersilie bestreuen.']::text[], array['Reis garen', 'Halal-Hähnchen anbraten', 'Gemüse braten', 'Zusammenführen', 'Servieren']::text[], array[20, 6, 6, 2, 0]::integer[], 'livo_original', 'LIVO original', 'LIVO recipe team', 'premium'),
  ('livo-gefuellte-paprika-tomaten', 'Gefüllte Paprika und Tomaten mit Reis', 'Griechisch inspiriert: Paprika und Tomaten mit Kräuterreis gefüllt und mit Kartoffeln im Ofen gegart.', 90, 25, 65, 'Mittel', 3, array['Abendessen', 'Vegan', 'Meal Prep']::text[], array['Auflaufform', 'Teelöffel zum Aushöhlen', 'Große Schüssel', 'Pfanne']::text[], array['Den Backofen auf 190 °C Ober- und Unterhitze vorheizen.', 'Von Paprika und Tomaten einen Deckel abschneiden. Paprika entkernen, Tomaten mit einem Teelöffel aushöhlen und das Tomateninnere fein hacken.', 'Die Hälfte des Öls erhitzen, Zwiebel und Knoblauch 3 Minuten dünsten. Tomatenmark, das klein geschnittene Tomateninnere, Reis, Oregano, Petersilie, Salz und Pfeffer untermischen und 3 Minuten köcheln.', 'Das Gemüse zu drei Vierteln füllen, da der Reis aufquillt, in die Form setzen und die Deckel auflegen. Kartoffelspalten dazwischen legen.', '200 ml Wasser in die Form gießen, alles mit dem restlichen Öl beträufeln und zugedeckt 40 Minuten backen. Dann ohne Deckel weitere 20 Minuten backen, bis Reis und Kartoffeln weich sind.']::text[], array['Ofen vorheizen', 'Aushöhlen', 'Füllung', 'Füllen', 'Backen']::text[], array[0, 0, 6, 0, 60]::integer[], 'livo_original', 'LIVO original', 'LIVO recipe team', 'premium'),
  ('livo-nudeln-tomatensauce', 'Nudeln mit Tomatensauce', 'Schnelle Tomatensauce aus der Dose mit Zwiebel, Knoblauch und Oregano – der Vorrats-Klassiker.', 25, 5, 20, 'Einfach', 2, array['Mittagessen', 'Abendessen', 'Vegan', 'Budget', 'Schnell']::text[], array['Großer Topf', 'Mittlerer Topf oder Pfanne', 'Sieb']::text[], array['Reichlich Wasser im großen Topf aufkochen und leicht salzen.', 'Das Öl im zweiten Topf erhitzen, die Zwiebel 3 Minuten glasig dünsten, dann Knoblauch und Tomatenmark 1 Minute mitrösten.', 'Dosentomaten und Oregano zugeben und die Sauce 10 Minuten offen köcheln lassen. Mit Salz und Pfeffer abschmecken.', 'Währenddessen die Nudeln nach Packungsangabe bissfest kochen. Vor dem Abgießen eine Tasse Nudelwasser abnehmen.', 'Die Nudeln abgießen, mit der Sauce vermengen und bei Bedarf mit etwas Nudelwasser cremiger machen.']::text[], array['Wasser aufsetzen', 'Sauce ansetzen', 'Köcheln', 'Nudeln kochen', 'Vermengen']::text[], array[5, 4, 10, 10, 0]::integer[], 'livo_original', 'LIVO original', 'LIVO recipe team', 'free'),
  ('livo-thunfisch-nudelsalat', 'Nudelsalat mit Thunfisch und Paprika', 'Bunter Nudelsalat mit Thunfisch, Paprika, Mais und Tomaten in einem Zitronen-Olivenöl-Dressing.', 25, 15, 10, 'Einfach', 3, array['Mittagessen', 'High Protein', 'Pescetarisch', 'Meal Prep']::text[], array['Großer Topf', 'Sieb', 'Große Schüssel', 'Schneidebrett und Messer']::text[], array['Die Nudeln in leicht gesalzenem Wasser bissfest kochen, abgießen und kalt abspülen.', 'Olivenöl, Zitronensaft, Salz und Pfeffer in der großen Schüssel verrühren.', 'Paprika und Tomaten würfeln, Zwiebel in feine Streifen schneiden, Mais abtropfen lassen und den Thunfisch zerpflücken.', 'Nudeln und alle Zutaten mit dem Dressing vermengen und 10 Minuten ziehen lassen, dann nochmals abschmecken.']::text[], array['Nudeln kochen', 'Dressing', 'Schneiden', 'Mischen']::text[], array[10, 0, 0, 10]::integer[], 'livo_original', 'LIVO original', 'LIVO recipe team', 'premium'),
  ('livo-spinat-feta-nudelauflauf', 'Nudelauflauf mit Spinat und Feta', 'Überbackene Nudeln mit TK-Spinat, Feta und einer einfachen Ei-Milch-Mischung.', 50, 15, 35, 'Einfach', 4, array['Abendessen', 'Vegetarisch', 'Meal Prep']::text[], array['Großer Topf', 'Pfanne', 'Auflaufform', 'Schüssel']::text[], array['Den Backofen auf 200 °C Ober- und Unterhitze vorheizen. Die Nudeln 2 Minuten kürzer als angegeben kochen und abgießen.', 'Das Öl erhitzen, Zwiebel und Knoblauch 3 Minuten dünsten, den ausgedrückten Spinat zugeben und 2 Minuten mitdünsten. Leicht salzen und pfeffern.', 'Eier und Milch verquirlen, die Hälfte des Fetas hineinbröseln.', 'Nudeln und Spinat in der Form mischen, die Eiermilch darüber gießen und den restlichen Feta darüberbröseln.', 'Den Auflauf 20 bis 25 Minuten backen, bis die Eiermilch gestockt ist und der Feta leicht bräunt.']::text[], array['Vorbereiten', 'Spinat dünsten', 'Eiermilch', 'Schichten', 'Backen']::text[], array[8, 5, 0, 0, 25]::integer[], 'livo_original', 'LIVO original', 'LIVO recipe team', 'premium'),
  ('livo-linsen-ragout', 'Linsen-Ragout mit Spaghetti', 'Herzhaftes Tomaten-Ragout aus roten Linsen, Möhren und Dosentomaten – vegan und gut zum Vorkochen.', 40, 10, 30, 'Einfach', 4, array['Abendessen', 'Mittagessen', 'Vegan', 'Budget', 'Meal Prep']::text[], array['Großer Topf', 'Zweiter Topf für die Nudeln', 'Reibe', 'Sieb']::text[], array['Das Öl im Topf erhitzen. Zwiebel und Möhre 5 Minuten dünsten, dann Knoblauch und Tomatenmark 1 Minute mitrösten.', 'Die gespülten Linsen, Dosentomaten, Brühe und Oregano zugeben und aufkochen.', 'Die Sauce 20 Minuten bei niedriger Hitze köcheln lassen, bis die Linsen weich sind. Regelmäßig umrühren und mit Salz und Pfeffer abschmecken.', 'Währenddessen die Nudeln in leicht gesalzenem Wasser bissfest kochen und abgießen.', 'Die Nudeln auf Teller verteilen und das Linsen-Ragout darüber geben.']::text[], array['Anschwitzen', 'Linsen zugeben', 'Köcheln', 'Nudeln kochen', 'Servieren']::text[], array[6, 0, 20, 10, 0]::integer[], 'livo_original', 'LIVO original', 'LIVO recipe team', 'premium'),
  ('livo-kichererbsen-curry', 'Kichererbsen-Tomaten-Curry', 'Würziges Curry aus Kichererbsen und Dosentomaten, fertig in 30 Minuten.', 30, 8, 22, 'Einfach', 3, array['Abendessen', 'Mittagessen', 'Vegan', 'Budget', 'Meal Prep']::text[], array['Großer Topf', 'Sieb', 'Schneidebrett und Messer']::text[], array['Das Öl im Topf erhitzen und die Zwiebeln bei mittlerer Hitze 6 Minuten goldgelb braten.', 'Knoblauch, Currypulver und Kreuzkümmel zugeben und 1 Minute unter Rühren rösten, bis es duftet.', 'Dosentomaten, Kichererbsen und 150 ml Wasser zugeben und 15 Minuten offen köcheln lassen. Einige Kichererbsen mit dem Löffel zerdrücken.', 'Mit Zitronensaft und Salz abschmecken und servieren.']::text[], array['Zwiebeln anbraten', 'Gewürze rösten', 'Köcheln', 'Abschmecken']::text[], array[6, 1, 15, 0]::integer[], 'livo_original', 'LIVO original', 'LIVO recipe team', 'premium'),
  ('livo-bohnen-chili', 'Bohnen-Chili mit Reis', 'Veganes Chili mit schwarzen Bohnen, Mais und Paprika, dazu Reis – ideal zum Vorkochen.', 45, 12, 33, 'Einfach', 4, array['Abendessen', 'Mittagessen', 'Vegan', 'Budget', 'Meal Prep']::text[], array['Großer Topf', 'Topf mit Deckel für den Reis', 'Sieb', 'Schneidebrett und Messer']::text[], array['Das Öl im großen Topf erhitzen. Zwiebeln und Paprika 5 Minuten braten, dann Knoblauch, Tomatenmark, Kreuzkümmel und Paprikapulver 1 Minute mitrösten.', 'Dosentomaten zugeben und 15 Minuten offen köcheln lassen.', 'Währenddessen den Reis mit 500 ml Wasser und einer Prise Salz aufkochen und zugedeckt 15 Minuten garen.', 'Bohnen und abgetropften Mais in das Chili geben und weitere 10 Minuten köcheln lassen. Mit Salz und Pfeffer abschmecken.', 'Das Chili mit dem Reis in Schalen anrichten.']::text[], array['Anbraten', 'Köcheln', 'Reis kochen', 'Bohnen und Mais', 'Servieren']::text[], array[6, 15, 15, 10, 0]::integer[], 'livo_original', 'LIVO original', 'LIVO recipe team', 'premium'),
  ('livo-ofenlachs-kartoffeln', 'Ofenlachs auf Kartoffeln und Zwiebeln', 'Lachsfilets auf Kartoffelscheiben und Zwiebeln aus einer Form – wenig Aufwand, viel Geschmack.', 50, 12, 38, 'Einfach', 3, array['Abendessen', 'High Protein', 'Pescetarisch']::text[], array['Große Auflaufform', 'Schneidebrett und Messer', 'Schüssel']::text[], array['Den Backofen auf 200 °C Ober- und Unterhitze vorheizen.', 'Kartoffelscheiben und Zwiebeln in der Form mit Öl, Salz und Pfeffer mischen und 25 Minuten backen.', 'Den Lachs trocken tupfen, mit Paprikapulver, Salz und etwas Zitronensaft würzen.', 'Den Lachs auf die Kartoffeln legen und alles weitere 12 bis 15 Minuten backen, bis der Lachs innen nicht mehr glasig ist.', 'Mit dem restlichen Zitronensaft beträufeln und direkt aus der Form servieren.']::text[], array['Ofen vorheizen', 'Kartoffeln vorbacken', 'Lachs würzen', 'Zusammen garen', 'Servieren']::text[], array[0, 25, 0, 13, 0]::integer[], 'livo_original', 'LIVO original', 'LIVO recipe team', 'premium'),
  ('livo-knusper-kichererbsen', 'Knusprige Paprika-Kichererbsen', 'Geröstete Kichererbsen aus dem Ofen – ein würziger Snack aus nur fünf Zutaten.', 35, 8, 27, 'Einfach', 2, array['Snack', 'Vegan', 'Budget']::text[], array['Backblech mit Backpapier', 'Sieb', 'Küchentuch', 'Schüssel']::text[], array['Den Backofen auf 200 °C Umluft vorheizen und ein Blech mit Backpapier belegen.', 'Die Kichererbsen abspülen, abtropfen lassen und mit einem Küchentuch sehr gründlich trocken reiben. Lose Häutchen entfernen.', 'Die Kichererbsen mit Öl, Paprikapulver, Kreuzkümmel und Salz in einer Schüssel vermengen.', 'Auf dem Blech verteilen und 25 bis 30 Minuten rösten, nach 15 Minuten einmal durchschütteln, bis sie knusprig sind.', 'Auf dem Blech abkühlen lassen – dabei werden sie noch knuspriger.']::text[], array['Vorheizen', 'Trocknen', 'Würzen', 'Rösten', 'Abkühlen']::text[], array[0, 0, 0, 27, 0]::integer[], 'livo_original', 'LIVO original', 'LIVO recipe team', 'premium'),
  ('livo-thunfisch-bohnen-salat', 'Thunfisch-Salat mit Ei, grünen Bohnen und Kichererbsen', 'Sättigender Salat mit Thunfisch aus der Dose, gekochten Eiern, grünen Bohnen und Kichererbsen.', 25, 12, 13, 'Einfach', 3, array['Mittagessen', 'Abendessen', 'High Protein', 'Pescetarisch', 'Meal Prep']::text[], array['Zwei Töpfe', 'Sieb', 'Große Schüssel']::text[], array['Die Eier 9 Minuten hart kochen, kalt abschrecken und pellen.', 'Die grünen Bohnen in kochendem Salzwasser 5 Minuten garen und in kaltem Wasser abschrecken.', 'Olivenöl, Zitronensaft, Salz und Pfeffer in der großen Schüssel verrühren und die Zwiebel untermischen.', 'Bohnen und Kichererbsen im Dressing wenden, auf Teller verteilen und mit zerpflücktem Thunfisch und geviertelten Eiern belegen.']::text[], array['Eier kochen', 'Bohnen garen', 'Dressing', 'Anrichten']::text[], array[9, 5, 0, 0]::integer[], 'livo_original', 'LIVO original', 'LIVO recipe team', 'premium'),
  ('livo-joghurt-gurken-dip', 'Joghurt-Gurken-Dip mit Möhrensticks', 'Frischer Dip nach Tzatziki-Art aus Joghurt, geriebener Gurke und Knoblauch, dazu knackige Möhren.', 15, 15, 0, 'Einfach', 3, array['Snack', 'Vegetarisch', 'Budget', 'Schnell']::text[], array['Reibe', 'Sieb', 'Schüssel', 'Schneidebrett und Messer']::text[], array['Die Gurke grob reiben, mit einer Prise Salz mischen und 5 Minuten in einem Sieb abtropfen lassen. Dann gut ausdrücken.', 'Joghurt mit Knoblauch, Zitronensaft, Salz und Pfeffer verrühren und die Gurke untermischen.', 'Die Möhren schälen und in fingerdicke Stifte schneiden.', 'Den Dip in eine Schale füllen, mit Olivenöl beträufeln und mit den Möhrensticks servieren.']::text[], array['Gurke reiben', 'Dip rühren', 'Möhren schneiden', 'Servieren']::text[], array[5, 0, 0, 0]::integer[], 'livo_original', 'LIVO original', 'LIVO recipe team', 'premium')
on conflict (slug) do update set
  title = excluded.title,
  description = excluded.description,
  preparation_minutes = excluded.preparation_minutes,
  prep_minutes = excluded.prep_minutes,
  cook_minutes = excluded.cook_minutes,
  difficulty = excluded.difficulty,
  servings = excluded.servings,
  tags = excluded.tags,
  equipment = excluded.equipment,
  instructions = excluded.instructions,
  step_titles = excluded.step_titles,
  step_minutes = excluded.step_minutes,
  source = excluded.source,
  source_license = excluded.source_license,
  source_attribution = excluded.source_attribution,
  access_level = excluded.access_level,
  updated_at = timezone('utc', now());

-- Early seed recipes replaced by the LIVO recipe set.
delete from public.recipes where slug in ('berry-protein-oats', 'salmon-power-bowl', 'vegetable-egg-pan', 'livo-chicken-rice-bowl', 'livo-chicken-avocado-plate');

-- Ingredient lists are replaced as a whole.
delete from public.recipe_ingredients
where recipe_id in (select id from public.recipes where slug in ('livo-protein-oats', 'livo-vegetable-egg-pan', 'livo-salmon-avocado-rice', 'livo-avocado-egg-bowl', 'livo-tomato-rice-pan', 'livo-skyr-berry-bowl', 'livo-salmon-tomato-bowl', 'livo-egg-avocado-breakfast', 'livo-skyr-oat-cup', 'livo-rice-egg-bowl', 'livo-apfel-zimt-porridge', 'livo-ruehrei-vollkornbrot', 'livo-bananen-hafer-pfannkuchen', 'livo-overnight-oats-banane', 'livo-pfannkuchen', 'livo-arme-ritter', 'livo-bananen-quark', 'livo-pellkartoffeln-kraeuterquark', 'livo-bratkartoffeln-spiegelei', 'livo-kartoffel-moehren-eintopf', 'livo-ofenkartoffeln-moehren', 'livo-kartoffelpuffer-apfelmus', 'livo-kartoffel-tortilla', 'livo-kartoffelsalat-gurke', 'livo-rote-linsen-dal', 'livo-mujaddara', 'livo-milchreis-zimt', 'livo-thunfisch-reis-bowl', 'livo-halal-haehnchen-paprika-reis', 'livo-gefuellte-paprika-tomaten', 'livo-nudeln-tomatensauce', 'livo-thunfisch-nudelsalat', 'livo-spinat-feta-nudelauflauf', 'livo-linsen-ragout', 'livo-kichererbsen-curry', 'livo-bohnen-chili', 'livo-ofenlachs-kartoffeln', 'livo-knusper-kichererbsen', 'livo-thunfisch-bohnen-salat', 'livo-joghurt-gurken-dip'));

insert into public.recipe_ingredients (recipe_id, food_id, amount_grams, position, measure, note)
select r.id, f.id, x.amount_grams, x.position, x.measure, x.note
from (values
  ('livo-protein-oats', 'oats', 50::numeric, 1, '5 EL'::text, null::text),
  ('livo-protein-oats', 'skyr', 200::numeric, 2, '1 Becher'::text, null::text),
