insert into public.recipe_premium_details (recipe_id, step_tips, common_mistakes,
  substitutions, meal_prep, variations, serving_tip)
select r.id, x.step_tips, x.common_mistakes, x.substitutions, x.meal_prep,
  x.variations, x.serving_tip
from (values
  ('livo-protein-oats', array['Mit warmem Wasser quellen die Flocken schneller und werden weicher.', '', 'Gefrorene Beeren über Nacht im Kühlschrank auftauen, dann ziehen sie Saft.']::text[], array['Zu wenig Flüssigkeit – dann wird die Masse klumpig und trocken.']::text[], array['Skyr durch Magerquark mit einem Schuss Milch ersetzen.', 'Statt Beeren eine halbe geriebene Birne oder einen Apfel verwenden.']::text[], 'Hafer und Skyr am Vorabend mischen und abgedeckt bis zu 24 Stunden kühlen; die Beeren erst morgens darauf geben.', array['Mit einer Prise Zimt und geriebenem Apfel.', 'Mit 1 TL Kakao für eine schokoladige Variante.']::text[], 'In einem Glas geschichtet lässt sich das Frühstück gut mitnehmen.'),
  ('livo-vegetable-egg-pan', array['', 'Die Zwiebel nur glasig werden lassen, nicht bräunen.', '', 'Der Deckel sorgt dafür, dass das Eiweiß oben fest wird, während das Eigelb weich bleibt.', '']::text[], array['Zu hohe Hitze – dann brennt das Gemüse an, bevor die Eier fest sind.']::text[], array['Frische Tomaten durch 200 g Dosentomaten ersetzen.', 'Paprika durch Zucchini ersetzen.']::text[], 'Die Gemüsesauce lässt sich 2 Tage vorher kochen; die Eier immer frisch darin garen.', array['Mit ½ TL Kreuzkümmel und Paprikapulver würzen.', 'Zum Schluss etwas Feta darüberbröseln.']::text[], 'Eine Scheibe Vollkornbrot zum Auftunken passt gut dazu.'),
  ('livo-salmon-avocado-rice', array['', 'Trocken getupfter Lachs bräunt besser und klebt weniger.', 'Den Lachs erst wenden, wenn er sich von selbst von der Pfanne löst.', 'Zitronensaft verhindert, dass die Avocado braun wird.', '']::text[], array['Den Lachs zu lange braten – dann wird er trocken.', 'Den Lachs zu oft bewegen, dann reißt die Haut.']::text[], array['Reis durch gekochte Vollkornpasta ersetzen.', 'Avocado durch Gurkenscheiben ersetzen, das spart Fett.']::text[], 'Reis und Lachs halten gekühlt 2 Tage; Avocado erst frisch aufschneiden.', array['Mit Frühlingszwiebeln und Sesam bestreuen.', 'Den Lachs vor dem Braten mit Paprikapulver würzen.']::text[], 'Mit ein paar Gurkenscheiben und Zitronenspalten servieren.'),
  ('livo-avocado-egg-bowl', array['Eier aus dem Kühlschrank brauchen etwa 1 Minute länger.', '', '']::text[], array['Die Eier nicht abschrecken – dann garen sie nach und lassen sich schlecht pellen.']::text[], array['Avocado durch Gurke ersetzen.', 'Tomate durch ein paar Maiskörner ersetzen.']::text[], 'Gekochte Eier halten ungeschält 5 Tage im Kühlschrank.', array['Mit Paprikapulver und Frühlingszwiebeln.', 'Mit einer Scheibe Vollkornbrot als Mittagessen.']::text[], 'Die Eier erst kurz vor dem Essen halbieren, dann bleibt das Eigelb cremig.'),
  ('livo-tomato-rice-pan', array['', 'Geröstetes Tomatenmark schmeckt runder und weniger sauer.', '', 'Reis vom Vortag klebt weniger als frisch gekochter.']::text[], array['Zu viel Rühren – dann wird der Reis matschig.']::text[], array['Frische Tomaten durch 1 Dose gehackte Tomaten ersetzen.', 'Zwiebel durch Frühlingszwiebeln ersetzen.']::text[], 'Hält gekühlt 2 Tage; gründlich durcherhitzen.', array['Mit Kichererbsen aus der Dose für mehr Eiweiß.', 'Mit einem Spiegelei obendrauf.']::text[], 'Mit Naturjoghurt und frischer Petersilie servieren.'),
  ('livo-skyr-berry-bowl', array['Ein Schuss Milch macht den Skyr noch cremiger.', '', '']::text[], array['Gefrorene Beeren direkt verwenden – dann wird der Skyr wässrig und kalt.']::text[], array['Skyr durch Magerquark ersetzen.', 'Honig weglassen oder durch eine zerdrückte Banane ersetzen.']::text[], 'In einem verschließbaren Glas hält die Bowl gekühlt bis zum nächsten Tag.', array['Mit 2 EL Haferflocken für mehr Biss.', 'Mit Zimt und Apfelwürfeln.']::text[], 'Gut gekühlt schmeckt die Bowl am besten.'),
  ('livo-salmon-tomato-bowl', array['', 'Zucchini nicht zu klein schneiden, sonst wird sie weich.', 'Der Lachs ist gar, wenn er sich leicht in Lamellen teilen lässt.', '']::text[], array['Die Pfanne überladen – dann dünstet die Zucchini statt zu braten.']::text[], array['Zucchini durch Paprika ersetzen.', 'Lachs durch Thunfisch aus der Dose ersetzen (kalt servieren).']::text[], 'Reis und Gemüse halten 2 Tage; den Lachs am besten frisch braten.', array['Mit Frühlingszwiebeln und etwas Joghurt-Dressing.', 'Mit Gurke statt Tomate für eine frische Sommer-Bowl.']::text[], 'Warm oder lauwarm servieren.'),
  ('livo-egg-avocado-breakfast', array['Mit einem Deckel wird das Eiweiß oben schneller fest.', '', '']::text[], array['Zu heiße Pfanne – dann wird der Rand zäh und braun.']::text[], array['Avocado durch Gurke ersetzen.', 'Spiegeleier durch gekochte Eier ersetzen.']::text[], 'Nicht zum Vorbereiten geeignet – frisch schmeckt es am besten.', array['Mit Paprikapulver oder Chiliflocken.', 'Avocado auf dem Brot zerdrücken und die Eier darauf legen.']::text[], 'Ein Spritzer Zitronensaft auf der Avocado macht das Frühstück frischer.'),
  ('livo-skyr-oat-cup', array['Die Flocken ständig bewegen, sie werden schnell zu dunkel.', '', '']::text[], array['Den Cup lange stehen lassen – dann verlieren die Flocken ihren Biss.']::text[], array['Skyr durch Naturjoghurt ersetzen (weniger Eiweiß).', 'Honig durch eine halbe zerdrückte Banane ersetzen.']::text[], 'Geröstete Haferflocken halten in einem Glas eine Woche; frisch schichten.', array['Mit Zimt in den gerösteten Flocken.', 'Mit Apfelwürfeln statt Beeren.']::text[], 'In einem durchsichtigen Glas sehen die Schichten besonders schön aus.'),
  ('livo-rice-egg-bowl', array['TK-Erbsen müssen nicht aufgetaut werden.', 'Den Reis zwischendurch liegen lassen, damit er Röstaromen bekommt.', '', '']::text[], array['Frisch gekochten, warmen Reis verwenden – der klebt und wird matschig.']::text[], array['Erbsen und Möhre durch 150 g TK-Gemüsemischung ersetzen.', 'Spiegelei durch Rührei ersetzen und direkt unter den Reis mischen.']::text[], 'Gekochten Reis schnell abkühlen und höchstens 1 Tag im Kühlschrank lagern.', array['Mit Paprikawürfeln und Mais.', 'Mit Currypulver für eine würzige Variante.']::text[], 'Ein paar Tropfen Zitronensaft zum Schluss machen den Reis frischer.'),
  ('livo-apfel-zimt-porridge', array['Regelmäßig rühren, sonst setzt die Milch am Boden an.', 'Säuerliche Äpfel wie Boskop behalten beim Dünsten ihre Form.', '']::text[], array['Zu hohe Hitze – Milch kocht schnell über.']::text[], array['Milch zur Hälfte durch Wasser ersetzen, das spart Energie.', 'Apfel durch eine Birne oder Banane ersetzen.']::text[], 'Zimtäpfel für 3 Tage vorkochen und gekühlt aufbewahren; Porridge morgens frisch kochen.', array['Mit 2 EL Naturjoghurt als Topping.', 'Mit geriebener Möhre und Zimt als Karottenkuchen-Porridge.']::text[], 'Etwas Zimt ganz zum Schluss darüberstäuben.'),
  ('livo-ruehrei-vollkornbrot', array['', 'Die Pfanne vom Herd nehmen, sobald das Ei noch leicht glänzt – es gart nach.', '', '']::text[], array['Zu hohe Hitze – das Ei wird trocken und krümelig.', 'Salz erst am Ende – so bleibt das Rührei weniger cremig; lieber vorher unterrühren.']::text[], array['Milch durch Wasser ersetzen.', 'Schnittlauch durch Frühlingszwiebeln ersetzen.']::text[], 'Rührei schmeckt frisch am besten; gekochte Eier sind die bessere Vorrats-Alternative.', array['Mit Tomatenwürfeln und Paprika.', 'Mit etwas Feta, dann weniger salzen.']::text[], 'Dazu passen Gurkenscheiben oder ein paar Tomaten.'),
  ('livo-bananen-hafer-pfannkuchen', array['Je reifer die Banane, desto süßer der Teig.', '', 'Erst wenden, wenn die Oberfläche kleine Bläschen zeigt.', '']::text[], array['Zu große Pfannkuchen – ohne Mehl zerbrechen sie beim Wenden.']::text[], array['Milch durch Wasser ersetzen.', 'Banane durch 100 g Apfelmus ersetzen.']::text[], 'Gebackene Pfannkuchen halten gekühlt 2 Tage und lassen sich gut einfrieren.', array['Mit Beeren im Teig.', 'Mit 2 EL Naturjoghurt als Topping.']::text[], 'Warm mit Joghurt und etwas Zimt servieren.'),
  ('livo-overnight-oats-banane', array['Kernige Haferflocken bleiben bissfester, zarte werden cremiger.', '', 'Ist die Masse zu fest, einen Schuss Milch unterrühren.']::text[], array['Zu wenig Flüssigkeit – die Haferflocken saugen viel auf.']::text[], array['Naturjoghurt durch Skyr ersetzen, das bringt mehr Eiweiß.', 'Banane durch Beeren oder Apfel ersetzen.']::text[], 'Hält gut verschlossen bis zu 2 Tage im Kühlschrank.', array['Mit 1 TL Kakao.', 'Mit geriebenem Apfel und extra Zimt.']::text[], 'Direkt aus dem Glas löffeln – ideal für unterwegs.'),
  ('livo-pfannkuchen', array['Erst die Milch zum Mehl geben, dann klumpt nichts.', '', 'Der erste Pfannkuchen ist oft ein Test – danach die Hitze anpassen.', 'Fertige Pfannkuchen im Ofen bei 80 °C warm halten.']::text[], array['Zu viel Öl in der Pfanne – die Pfannkuchen werden fettig.', 'Zu dicker Teig – dann einen Schuss Milch ergänzen.']::text[], array['Die Hälfte des Mehls durch Vollkornmehl ersetzen.', 'Milch zur Hälfte durch Mineralwasser ersetzen, das macht sie luftiger.']::text[], 'Pfannkuchen mit Backpapier dazwischen stapeln; sie halten gekühlt 2 Tage oder eingefroren 2 Monate.', array['Süß mit Apfelmus und Zimt.', 'Herzhaft mit Spinat und Feta gefüllt.']::text[], 'Warm, gerollt und mit etwas Apfelmus servieren.'),
  ('livo-arme-ritter', array['', 'Trockenes Brot saugt mehr auf, ohne zu zerfallen.', 'Nicht zu heiß braten, sonst ist das Brot außen dunkel und innen noch nass.', '']::text[], array['Frisches, weiches Brot zu lange einweichen – es zerfällt.']::text[], array['Honig durch Apfelmus ersetzen.', 'Butter durch Rapsöl ersetzen.']::text[], 'Gebratene Scheiben lassen sich im Toaster aufwärmen; sie halten gekühlt 1 Tag.', array['Mit Beeren und Joghurt.', 'Herzhaft ohne Zimt und Honig, dafür mit Salz, Pfeffer und Schnittlauch.']::text[], 'Mit frischen Apfelscheiben oder Beeren servieren.'),
  ('livo-bananen-quark', array['Mehr Milch ergibt eine luftigere, weniger feste Creme.', 'Je brauner die Banane, desto süßer.', '']::text[], array['Quark ohne Flüssigkeit verwenden – er bleibt fest und trocken.']::text[], array['Magerquark durch Skyr ersetzen.', 'Haferflocken in der Pfanne rösten für mehr Aroma.']::text[], 'Die Quarkcreme hält gekühlt 1 Tag; Haferflocken erst kurz vorher darüber geben.', array['Mit Beeren statt Banane.', 'Mit geriebenem Apfel und extra Zimt.']::text[], 'Gut gekühlt als Nachmittagssnack genießen.'),
  ('livo-pellkartoffeln-kraeuterquark', array['Gleich große Kartoffeln werden gleichzeitig gar.', 'Den Quark 10 Minuten ziehen lassen, dann schmecken die Kräuter stärker.', 'Heiße Kartoffeln lassen sich mit einer Gabel festhalten und leicht pellen.', '']::text[], array['Zu große und kleine Kartoffeln mischen – dann sind manche zerkocht.']::text[], array['Schnittlauch durch Petersilie oder TK-Kräuter ersetzen.', 'Magerquark durch Skyr oder Naturjoghurt ersetzen.']::text[], 'Gekochte Kartoffeln halten gekühlt 3 Tage und eignen sich perfekt für Bratkartoffeln.', array['Mit Gurkenwürfeln im Quark.', 'Mit 1 TL Leinöl über dem Quark, wie in der Lausitz.']::text[], 'Mit Gurkensalat oder Radieschen servieren.'),
  ('livo-bratkartoffeln-spiegelei', array['Kalte, gekochte Kartoffeln zerfallen nicht und werden knuspriger als rohe.', 'Geduld: Erst wenden, wenn die Unterseite eine goldene Kruste hat.', 'Zwiebeln erst jetzt dazugeben, sonst verbrennen sie.', '', '']::text[], array['Die Pfanne überfüllen – dann dämpfen die Kartoffeln statt zu braten.', 'Zu früh salzen – das zieht Wasser und verhindert die Kruste.']::text[], array['Spiegeleier durch Rührei ersetzen.', 'Rapsöl durch Butterschmalz ersetzen.']::text[], 'Kartoffeln am Vortag kochen und ungeschnitten kühlen.', array['Mit Paprikawürfeln und Frühlingszwiebeln.', 'Mit Kräuterquark statt Ei.']::text[], 'Ein frischer Gurkensalat passt sehr gut dazu.'),
  ('livo-kartoffel-moehren-eintopf', array['Gleich große Stücke garen gleichmäßig.', '', 'Einige Kartoffelstücke mit dem Löffel zerdrücken, dann wird der Eintopf sämiger.', 'Die Brühe ist schon salzig – erst probieren, dann salzen.']::text[], array['Zu stark kochen – die Kartoffeln zerfallen und der Eintopf wird trüb.']::text[], array['Möhren teilweise durch Erbsen (TK) ersetzen.', 'Petersilie durch Schnittlauch ersetzen.']::text[], 'Hält gekühlt 3 Tage und lässt sich portionsweise einfrieren.', array['Mit 1 TL Paprikapulver und Kreuzkümmel würziger machen.', 'Zum Schluss 1 Dose weiße Bohnen oder Kichererbsen für mehr Eiweiß.']::text[], 'Mit einer Scheibe Vollkornbrot servieren.'),
  ('livo-ofenkartoffeln-moehren', array['', 'Kartoffeln vorher gut trocken tupfen, dann werden sie knuspriger.', 'Nicht stapeln – jedes Stück braucht Kontakt zum Blech.', '', '']::text[], array['Möhren zu dünn schneiden – sie verbrennen, bevor die Kartoffeln gar sind.']::text[], array['Möhren durch Paprika oder Zucchini ersetzen (dann erst nach 15 Minuten dazugeben).', 'Naturjoghurt durch Magerquark ersetzen.']::text[], 'Reste halten gekühlt 3 Tage und schmecken aufgewärmt in der Pfanne.', array['Mit Kichererbsen aus der Dose auf dem Blech.', 'Mit Oregano und etwas Feta nach dem Backen.']::text[], 'Mit etwas Petersilie bestreuen und direkt vom Blech servieren.'),
  ('livo-kartoffelpuffer-apfelmus', array['Zügig arbeiten, sonst werden die Kartoffeln braun.', 'Je trockener die Masse, desto knuspriger die Puffer.', '', 'Das Öl ist heiß genug, wenn ein Stück Kartoffel sofort brutzelt.', 'Im Ofen bei 100 °C bleiben fertige Puffer knusprig warm.']::text[], array['Die Masse nicht ausdrücken – die Puffer werden weich und saugen Öl.', 'Zu dicke Puffer – außen dunkel, innen roh.']::text[], array['Apfelmus durch Kräuterquark ersetzen für eine herzhafte Variante.', 'Ein Drittel der Kartoffeln durch Möhren oder Zucchini ersetzen.']::text[], 'Gebackene Puffer halten gekühlt 2 Tage; im Ofen oder in der Pfanne ohne Öl aufknuspern.', array['Mit Schnittlauch und Pfeffer im Teig.', 'Kleine Puffer als Snack mit Joghurt-Dip.']::text[], 'Sofort servieren, solange sie knusprig sind.'),
  ('livo-kartoffel-tortilla', array['Die Kartoffeln sollen weich werden, nicht knusprig.', 'Das Ziehenlassen verbindet Ei und Kartoffeln – so wird die Tortilla saftig.', 'Niedrige Hitze verhindert einen verbrannten Boden.', 'Mutig und in einer Bewegung stürzen.', '']::text[], array['Zu hohe Hitze beim Stocken – außen braun, innen flüssig.', 'Kartoffelscheiben zu dick schneiden.']::text[], array['Olivenöl durch Rapsöl ersetzen.', 'Einen Teil der Kartoffeln durch Paprika ersetzen.']::text[], 'Die Tortilla hält gekühlt 3 Tage und schmeckt auch kalt – ideal für die Brotdose.', array['Mit Spinat (TK) in der Eimasse.', 'Mit Paprikapulver und Frühlingszwiebeln.']::text[], 'Lauwarm mit einem Tomatensalat servieren.'),
  ('livo-kartoffelsalat-gurke', array['', 'So wird der Salat später nicht wässrig.', '', 'Lauwarme Kartoffeln nehmen das Dressing besser auf.', 'Vor dem Servieren nochmals abschmecken – Kartoffeln schlucken Salz.']::text[], array['Mehligkochende Kartoffeln verwenden – sie zerfallen im Salat.']::text[], array['Naturjoghurt teilweise durch Magerquark ersetzen.', 'Frühlingszwiebeln durch eine halbe rote Zwiebel ersetzen.']::text[], 'Hält gekühlt 2 Tage; Schnittlauch erst kurz vor dem Essen darüber geben.', array['Mit gehackten gekochten Eiern.', 'Mit Radieschen und Dill.']::text[], 'Gut gekühlt zum Grillen oder als Mittagessen mit einem Spiegelei.'),
  ('livo-rote-linsen-dal', array['Spülen entfernt Stärke, dann schäumt das Dal weniger.', '', 'Die Gewürze nur kurz rösten, sonst werden sie bitter.', 'Wird es zu dick, einen Schuss Wasser ergänzen.', 'Zitronensaft hebt den Geschmack deutlich.']::text[], array['Zu wenig rühren – rote Linsen setzen schnell am Topfboden an.']::text[], array['Dosentomaten durch 3 frische Tomaten ersetzen.', 'Einen Teil der Brühe durch Kokosmilch ersetzen, wenn vorhanden.']::text[], 'Dal hält gekühlt 4 Tage und lässt sich gut einfrieren; Reis höchstens 1 Tag lagern.', array['Zum Schluss 200 g Spinat (TK) unterrühren.', 'Mit Naturjoghurt als Topping (dann vegetarisch).']::text[], 'Mit frischer Petersilie und einem Zitronenschnitz servieren.'),
  ('livo-mujaddara', array['Tellerlinsen dürfen noch leichten Biss haben – sie garen mit dem Reis weiter.', 'Geduld lohnt sich: Die Süße der Zwiebeln macht das Gericht aus.', 'Den Deckel während des Garens nicht öffnen.', '', '']::text[], array['Zwiebeln bei zu hoher Hitze rösten – sie werden bitter statt süß.']::text[], array['Tellerlinsen durch braune Linsen aus der Dose ersetzen (dann Schritt 1 weglassen).', 'Naturjoghurt durch Gurken-Joghurt ersetzen.']::text[], 'Hält gekühlt 3 Tage; die Röstzwiebeln getrennt aufbewahren, damit sie knusprig bleiben.', array['Mit Zimt und etwas Pfeffer in den Zwiebeln.', 'Mit einem Tomaten-Gurken-Salat als Beilage.']::text[], 'Warm oder lauwarm mit kaltem Joghurt servieren.'),
  ('livo-milchreis-zimt', array['Den Topf vorher kalt ausspülen, dann setzt die Milch weniger an.', 'Kurz vor Ende wird der Reis dicker – dann häufiger rühren.', '', '']::text[], array['Zu hohe Hitze – die Milch brennt an und schmeckt bitter.']::text[], array['Honig durch Zucker oder Apfelmus ersetzen.', 'Einen Teil der Milch durch Wasser ersetzen, das spart Energie.']::text[], 'Hält gekühlt 3 Tage; kalt wird er fester, dann mit etwas Milch aufwärmen.', array['Mit gedünsteten Apfelwürfeln.', 'Mit Beeren oder Kirschen aus dem Glas.']::text[], 'Warm oder kalt aus dem Kühlschrank genießen.'),
  ('livo-thunfisch-reis-bowl', array['Reis vorher waschen, dann klebt er weniger.', '', 'Thunfisch gut abtropfen lassen, sonst wird die Bowl wässrig.', '']::text[], array['Das Dressing zu früh darüber geben – der Reis saugt es auf.']::text[], array['Reis vom Vortag verwenden, dann ist die Bowl in 10 Minuten fertig.', 'Mais durch Paprikawürfel ersetzen.']::text[], 'Reis, Gemüse und Dressing getrennt aufbewahren; hält gekühlt 1 Tag.', array['Mit Avocado und Tomate.', 'Mit einem gekochten Ei für noch mehr Eiweiß.']::text[], 'Warmer Reis mit kühlem Topping ist besonders lecker.'),
  ('livo-halal-haehnchen-paprika-reis', array['', 'Nicht zu viel auf einmal in die Pfanne geben, dann bräunt das Halal-Hähnchen statt zu kochen.', 'Paprika soll noch leichten Biss haben.', '', '']::text[], array['Das Halal-Hähnchen nicht vollständig durchgaren – Geflügel muss innen weiß sein.', 'Schneidebrett für rohes Geflügel nicht gründlich reinigen.']::text[], array['Das Halal-Hähnchen durch Kichererbsen aus der Dose ersetzen für eine vegane Variante.', 'Paprika teilweise durch Zucchini ersetzen.']::text[], 'Hält gekühlt 2 Tage; beim Aufwärmen vollständig durcherhitzen.', array['Mit Kreuzkümmel und etwas Zitronensaft.', 'Mit Erbsen (TK) im Reis.']::text[], 'Mit einem Klecks Naturjoghurt servieren. Beim Einkauf auf eine eindeutige Halal-Zertifizierung achten.'),
  ('livo-gefuellte-paprika-tomaten', array['', 'Die Paprika unten nicht verletzen, sonst läuft die Füllung aus.', 'Der Reis wird erst im Ofen gar.', '', 'Mit einem Messer prüfen, ob die Kartoffeln weich sind.']::text[], array['Zu wenig Flüssigkeit in der Form – der Reis bleibt hart.']::text[], array['Tomaten durch weitere Paprika ersetzen.', 'Mit Feta über der Füllung wird es vegetarisch statt vegan.']::text[], 'Hält gekühlt 3 Tage und schmeckt aufgewärmt fast noch besser.', array['Mit Zucchini als zusätzlichem Gefäß.', 'Mit Kreuzkümmel und Zimt in der Füllung.']::text[], 'Mit Naturjoghurt oder einem Joghurt-Gurken-Dip servieren.'),
  ('livo-nudeln-tomatensauce', array['', 'Tomatenmark kurz rösten nimmt ihm die Säure.', 'Ist die Sauce zu sauer, eine Prise Zucker oder etwas geriebene Möhre zugeben.', '', 'Die Stärke im Nudelwasser bindet die Sauce.']::text[], array['Die Sauce zu kurz kochen – sie schmeckt dann wässrig und roh.']::text[], array['Nudeln durch Vollkornnudeln ersetzen.', 'Oregano durch frisches Basilikum ersetzen.']::text[], 'Die Sauce hält gekühlt 4 Tage und lässt sich gut einfrieren – gleich die doppelte Menge kochen.', array['Mit Thunfisch aus der Dose.', 'Mit roten Linsen für ein sämiges Linsen-Ragout.']::text[], 'Mit etwas geriebenem Käse und Pfeffer servieren.'),
  ('livo-thunfisch-nudelsalat', array['Kaltes Abspülen stoppt den Garprozess und verhindert Verkleben.', '', 'Rote Zwiebel kurz in kaltes Wasser legen, dann ist sie milder.', 'Nudeln ziehen Dressing – vor dem Servieren eventuell noch etwas Zitrone zugeben.']::text[], array['Nudeln zu weich kochen – im Salat werden sie matschig.']::text[], array['Mais durch Gurke ersetzen.', 'Thunfisch durch Kichererbsen ersetzen (dann vegan).']::text[], 'Hält gut verschlossen 2 Tage im Kühlschrank – ideal für die Brotdose.', array['Mit Joghurt-Dressing statt Olivenöl.', 'Mit Oregano und Feta griechisch abwandeln.']::text[], 'Leicht gekühlt, aber nicht eiskalt servieren – so schmeckt er am besten.'),
  ('livo-spinat-feta-nudelauflauf', array['Die Nudeln garen im Ofen weiter.', 'Spinat gut ausdrücken, sonst wird der Auflauf wässrig.', 'Feta ist salzig – deshalb kaum zusätzlich salzen.', '', 'Vor dem Anschneiden 5 Minuten ruhen lassen.']::text[], array['Nudeln voll durchkochen – im Ofen werden sie dann zu weich.']::text[], array['Feta durch geriebenen Käse ersetzen (Lab-Art prüfen).', 'Spinat durch Brokkoli (TK) ersetzen.']::text[], 'Hält gekühlt 3 Tage; portionsweise in der Mikrowelle oder im Ofen aufwärmen.', array['Mit Tomatenwürfeln zwischen den Nudeln.', 'Mit Muskat in der Eiermilch.']::text[], 'Mit einem frischen Tomatensalat servieren.'),
  ('livo-linsen-ragout', array['Fein geriebene Möhre macht die Sauce süßer und sämiger.', '', 'Wird die Sauce zu dick, etwas Wasser nachgießen.', '', '']::text[], array['Die Linsen zu kurz kochen – sie bleiben dann körnig.']::text[], array['Rote Linsen durch Tellerlinsen ersetzen (dann 35 Minuten kochen).', 'Spaghetti durch Vollkornnudeln ersetzen.']::text[], 'Die Sauce hält gekühlt 4 Tage und lässt sich hervorragend einfrieren.', array['Mit Paprikawürfeln oder Zucchini.', 'Als Lasagne-Füllung verwenden.']::text[], 'Mit frischer Petersilie und Pfeffer servieren.'),
  ('livo-kichererbsen-curry', array['Gut gebräunte Zwiebeln geben dem Curry Tiefe.', 'Die Gewürze nur kurz rösten, sonst werden sie bitter.', 'Zerdrückte Kichererbsen binden die Sauce ohne Sahne.', '']::text[], array['Die Kichererbsen nicht abspülen – das Curry wird schaumig und salzig.']::text[], array['Einen Teil des Wassers durch Kokosmilch ersetzen, wenn vorhanden.', 'Kichererbsen teilweise durch Kartoffelwürfel ersetzen (dann 20 Minuten köcheln).']::text[], 'Hält gekühlt 4 Tage und schmeckt am zweiten Tag noch intensiver.', array['Zum Schluss 200 g Spinat (TK) unterrühren.', 'Mit Naturjoghurt als Topping (dann vegetarisch).']::text[], 'Mit Reis oder Fladenbrot servieren.'),
  ('livo-bohnen-chili', array['Geröstete Gewürze geben mehr Aroma als nachträglich eingerührte.', 'Je länger das Chili köchelt, desto runder schmeckt es.', '', 'Bohnen erst spät zugeben, dann bleiben sie ganz.', '']::text[], array['Das Chili zu dünn lassen – lieber offen einkochen, bis es sämig ist.']::text[], array['Schwarze Bohnen durch Kidneybohnen ersetzen.', 'Einen Teil der Bohnen durch rote Linsen ersetzen (mit etwas mehr Wasser).']::text[], 'Das Chili hält gekühlt 4 Tage und lässt sich portionsweise einfrieren.', array['Mit einer Prise Zimt und Chiliflocken.', 'Mit Naturjoghurt und Frühlingszwiebeln als Topping.']::text[], 'Mit frischen Kräutern und einem Zitronenschnitz servieren.'),
  ('livo-ofenlachs-kartoffeln', array['', 'Dünne, gleich dicke Scheiben garen gleichmäßig.', '', 'Der Lachs ist gar, wenn er sich mit einer Gabel leicht teilen lässt.', '']::text[], array['Den Lachs von Anfang an mitbacken – er wird trocken, bevor die Kartoffeln weich sind.']::text[], array['Lachs durch Seelachs (TK) ersetzen, dann 2 Minuten kürzer garen.', 'Zwiebeln teilweise durch Möhrenscheiben ersetzen.']::text[], 'Reste halten gekühlt 1 Tag und schmecken kalt mit Joghurt-Dip.', array['Mit Oregano und Tomatenscheiben.', 'Mit Brokkoli (TK) für die letzten 12 Minuten.']::text[], 'Mit Joghurt-Gurken-Dip oder einem grünen Salat servieren.'),
  ('livo-knusper-kichererbsen', array['', 'Je trockener die Kichererbsen, desto knuspriger das Ergebnis.', '', 'Bei dunklen Stellen die Temperatur etwas senken.', '']::text[], array['Nasse Kichererbsen rösten – sie bleiben weich und zäh.']::text[], array['Paprikapulver durch Currypulver ersetzen.', 'Olivenöl durch Rapsöl ersetzen.']::text[], 'Offen oder in einer Papiertüte halten sie 2 Tage knusprig; luftdicht werden sie weich.', array['Süß mit Zimt und etwas Honig nach dem Rösten.', 'Mit Oregano und Knoblauchpulver.']::text[], 'Als Snack oder als Topping für Salate und Suppen.'),
  ('livo-thunfisch-bohnen-salat', array['Abschrecken verhindert einen grauen Rand am Eigelb.', 'Abschrecken erhält die grüne Farbe.', '', '']::text[], array['Die Bohnen zu weich kochen – sie sollen noch knacken.']::text[], array['Grüne Bohnen durch Gurke und Tomate ersetzen (dann ohne Kochen).', 'Kichererbsen durch weiße Bohnen ersetzen.']::text[], 'Bestandteile getrennt aufbewahren; Eier und Bohnen halten gekühlt 3 Tage.', array['Mit gekochten Kartoffeln für eine sättigendere Variante.', 'Mit Joghurt-Dressing statt Öl und Zitrone.']::text[], 'Mit einer Scheibe Vollkornbrot servieren.'),
  ('livo-joghurt-gurken-dip', array['Gut ausgedrückte Gurke verhindert, dass der Dip wässrig wird.', '10 Minuten Ziehzeit machen den Knoblauch milder.', '', '']::text[], array['Zu viel Knoblauch – er wird beim Stehen immer schärfer.']::text[], array['Naturjoghurt teilweise durch Skyr ersetzen, dann wird der Dip fester.', 'Möhren durch Paprika- oder Gurkensticks ersetzen.']::text[], 'Der Dip hält gekühlt 2 Tage, Möhrensticks in Wasser gelagert 3 Tage.', array['Mit frischem Dill oder Minze.', 'Als Beilage zu Ofenkartoffeln oder gefüllter Paprika.']::text[], 'Gut gekühlt mit Vollkornbrot oder Gemüsesticks servieren.')
) as x(recipe_slug, step_tips, common_mistakes, substitutions, meal_prep, variations, serving_tip)
join public.recipes r on r.slug = x.recipe_slug
on conflict (recipe_id) do update set
  step_tips = excluded.step_tips,
  common_mistakes = excluded.common_mistakes,
  substitutions = excluded.substitutions,
  meal_prep = excluded.meal_prep,
  variations = excluded.variations,
  serving_tip = excluded.serving_tip;

-- The halal triggers skip rows silently; fail loudly instead so a
-- partial import can never go live.
do $$
begin
  if (select count(*) from public.recipes where slug in ('livo-protein-oats', 'livo-vegetable-egg-pan', 'livo-salmon-avocado-rice', 'livo-avocado-egg-bowl', 'livo-tomato-rice-pan', 'livo-skyr-berry-bowl', 'livo-salmon-tomato-bowl', 'livo-egg-avocado-breakfast', 'livo-skyr-oat-cup', 'livo-rice-egg-bowl', 'livo-apfel-zimt-porridge', 'livo-ruehrei-vollkornbrot', 'livo-bananen-hafer-pfannkuchen', 'livo-overnight-oats-banane', 'livo-pfannkuchen', 'livo-arme-ritter', 'livo-bananen-quark', 'livo-pellkartoffeln-kraeuterquark', 'livo-bratkartoffeln-spiegelei', 'livo-kartoffel-moehren-eintopf', 'livo-ofenkartoffeln-moehren', 'livo-kartoffelpuffer-apfelmus', 'livo-kartoffel-tortilla', 'livo-kartoffelsalat-gurke', 'livo-rote-linsen-dal', 'livo-mujaddara', 'livo-milchreis-zimt', 'livo-thunfisch-reis-bowl', 'livo-halal-haehnchen-paprika-reis', 'livo-gefuellte-paprika-tomaten', 'livo-nudeln-tomatensauce', 'livo-thunfisch-nudelsalat', 'livo-spinat-feta-nudelauflauf', 'livo-linsen-ragout', 'livo-kichererbsen-curry', 'livo-bohnen-chili', 'livo-ofenlachs-kartoffeln', 'livo-knusper-kichererbsen', 'livo-thunfisch-bohnen-salat', 'livo-joghurt-gurken-dip')) <> 40 then
    raise exception 'LIVO: nicht alle 40 Rezepte wurden gespeichert';
  end if;
  if (select count(*) from public.recipe_ingredients i
      join public.recipes r on r.id = i.recipe_id
      where r.slug in ('livo-protein-oats', 'livo-vegetable-egg-pan', 'livo-salmon-avocado-rice', 'livo-avocado-egg-bowl', 'livo-tomato-rice-pan', 'livo-skyr-berry-bowl', 'livo-salmon-tomato-bowl', 'livo-egg-avocado-breakfast', 'livo-skyr-oat-cup', 'livo-rice-egg-bowl', 'livo-apfel-zimt-porridge', 'livo-ruehrei-vollkornbrot', 'livo-bananen-hafer-pfannkuchen', 'livo-overnight-oats-banane', 'livo-pfannkuchen', 'livo-arme-ritter', 'livo-bananen-quark', 'livo-pellkartoffeln-kraeuterquark', 'livo-bratkartoffeln-spiegelei', 'livo-kartoffel-moehren-eintopf', 'livo-ofenkartoffeln-moehren', 'livo-kartoffelpuffer-apfelmus', 'livo-kartoffel-tortilla', 'livo-kartoffelsalat-gurke', 'livo-rote-linsen-dal', 'livo-mujaddara', 'livo-milchreis-zimt', 'livo-thunfisch-reis-bowl', 'livo-halal-haehnchen-paprika-reis', 'livo-gefuellte-paprika-tomaten', 'livo-nudeln-tomatensauce', 'livo-thunfisch-nudelsalat', 'livo-spinat-feta-nudelauflauf', 'livo-linsen-ragout', 'livo-kichererbsen-curry', 'livo-bohnen-chili', 'livo-ofenlachs-kartoffeln', 'livo-knusper-kichererbsen', 'livo-thunfisch-bohnen-salat', 'livo-joghurt-gurken-dip')) <> 307 then
    raise exception 'LIVO: nicht alle 307 Zutaten wurden gespeichert';
  end if;
  if (select count(*) from public.recipe_premium_details d
      join public.recipes r on r.id = d.recipe_id
      where r.slug in ('livo-protein-oats', 'livo-vegetable-egg-pan', 'livo-salmon-avocado-rice', 'livo-avocado-egg-bowl', 'livo-tomato-rice-pan', 'livo-skyr-berry-bowl', 'livo-salmon-tomato-bowl', 'livo-egg-avocado-breakfast', 'livo-skyr-oat-cup', 'livo-rice-egg-bowl', 'livo-apfel-zimt-porridge', 'livo-ruehrei-vollkornbrot', 'livo-bananen-hafer-pfannkuchen', 'livo-overnight-oats-banane', 'livo-pfannkuchen', 'livo-arme-ritter', 'livo-bananen-quark', 'livo-pellkartoffeln-kraeuterquark', 'livo-bratkartoffeln-spiegelei', 'livo-kartoffel-moehren-eintopf', 'livo-ofenkartoffeln-moehren', 'livo-kartoffelpuffer-apfelmus', 'livo-kartoffel-tortilla', 'livo-kartoffelsalat-gurke', 'livo-rote-linsen-dal', 'livo-mujaddara', 'livo-milchreis-zimt', 'livo-thunfisch-reis-bowl', 'livo-halal-haehnchen-paprika-reis', 'livo-gefuellte-paprika-tomaten', 'livo-nudeln-tomatensauce', 'livo-thunfisch-nudelsalat', 'livo-spinat-feta-nudelauflauf', 'livo-linsen-ragout', 'livo-kichererbsen-curry', 'livo-bohnen-chili', 'livo-ofenlachs-kartoffeln', 'livo-knusper-kichererbsen', 'livo-thunfisch-bohnen-salat', 'livo-joghurt-gurken-dip')) <> 40 then
    raise exception 'LIVO: nicht alle Premium-Details wurden gespeichert';
  end if;
end
